import queue

import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many elements of xs a bounded queue accepts.

    Creates a queue of integers holding at most `cap` items and tries to
    put each element of xs in order without blocking. Nothing is ever
    taken out of the queue. Stops at the first put that fails because
    the queue is full, and returns the number of puts accepted before
    that point.

    A capacity of zero or less accepts nothing, so the result is 0
    (it is not treated as an unbounded queue).
    """
    if cap <= 0:
        return 0
    q: queue.Queue[int] = queue.Queue(maxsize=cap)
    count = 0
    for x in xs:
        try:
            q.put_nowait(x)
        except queue.Full:
            break
        count += 1
    return count


def test_fewer_items_than_capacity() -> None:
    assert accepted(5, [1, 2, 3]) == 3


def test_exactly_capacity() -> None:
    assert accepted(3, [7, 8, 9]) == 3


def test_more_items_than_capacity() -> None:
    assert accepted(2, [1, 2, 3, 4, 5]) == 2


def test_empty_input() -> None:
    assert accepted(4, []) == 0


def test_zero_capacity_accepts_nothing() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_negative_capacity_accepts_nothing() -> None:
    assert accepted(-1, [1, 2]) == 0


def test_duplicates_are_all_counted() -> None:
    assert accepted(3, [4, 4, 4, 4]) == 3


def test_does_not_mutate_input() -> None:
    xs = [1, 2, 3, 4]
    accepted(2, xs)
    assert xs == [1, 2, 3, 4]


@pytest.mark.parametrize(
    ("cap", "n", "expected"),
    [(1, 1, 1), (1, 10, 1), (10, 1, 1), (10, 10, 10), (10, 100, 10)],
)
def test_accepted_is_min_of_cap_and_len(cap: int, n: int, expected: int) -> None:
    assert accepted(cap, list(range(n))) == expected

